        setCookie(needCookie, req, "127.0.0.1:7979");
        req.addHeader("routed", isRouted);
        val res = new MockHttpServletResponse();
        sparderUIService.proxy("123", "321", server, req, res);
        ArgumentCaptor<LogEvent> logCaptor = ArgumentCaptor.forClass(LogEvent.class);
        Mockito.verify(appender, Mockito.atLeast(0)).append(logCaptor.capture());
        var logs = logCaptor.getAllValues().stream().filter(event -> event.getLoggerName().equals("org.apache.kylin.rest.service.SparderUIService")).filter(event -> event.getLevel().equals(Level.INFO)).map(event -> event.getMessage().getFormattedMessage()).collect(Collectors.toList());
        if ((StringUtils.isNotBlank(server) || needCookie) && needRoute && !isRouted) {
            assertEquals(1, logs.size());
            assertTrue(StringUtils.equals(logs.get(0), "proxy sparder UI to server : [127.0.0.1:7979] queryId : [321] Id : [123]"));
        } else {
            assertTrue(CollectionUtils.isEmpty(logs));
        }
